--keel:notx
-- Rollup detention_daily of detention_occurrences, generated by keel's analytics/rollup. Do not edit; change the declaration and generate again.
CREATE TABLE IF NOT EXISTS keel_rollup_dirty (
    rollup text COLLATE "C" NOT NULL,
    tenant_key text COLLATE "C" NOT NULL,
    bucket timestamptz NOT NULL,
    xid xid8 NOT NULL,
    marked_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (rollup, tenant_key, bucket, xid)
);
CREATE INDEX IF NOT EXISTS keel_rollup_dirty_marked ON keel_rollup_dirty (marked_at);
CREATE TABLE IF NOT EXISTS keel_rollup_state (
    rollup text COLLATE "C" PRIMARY KEY,
    ready_at timestamptz NOT NULL
);
DELETE FROM keel_rollup_state WHERE rollup = 'detention_daily';
DELETE FROM keel_rollup_dirty WHERE rollup = 'detention_daily';
DO $keel$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_class WHERE oid = to_regclass('"detention_daily"') AND obj_description(oid, 'pg_class') = 'keel rollup detention_daily of detention_occurrences') THEN
        DROP TABLE "detention_daily";
    END IF;
END
$keel$;
CREATE TABLE "detention_daily" AS SELECT s."business_unit_id" AS "business_unit_id", s."organization_id" AS "organization_id", date_trunc('day', to_timestamp(s."clock_start_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = s."organization_id"), 'UTC'))) AS "bucket", count(*) AS "row_count", count(*) FILTER (WHERE CAST(greatest((s."raw_dwell_minutes" - s."free_minutes_granted"), 0::integer) AS bigint) > 0) AS "detained_stops", sum(CAST(greatest((s."raw_dwell_minutes" - s."free_minutes_granted"), 0::integer) AS bigint)) AS "past_free_minutes", sum(CAST(greatest((s."raw_dwell_minutes" - s."free_minutes_granted"), 0::integer) AS bigint)) FILTER (WHERE (NOT (s."arrived_late" IS TRUE) AND NOT (s."schedule_type" = 'Open') AND NOT ((s."appointment_start" IS NOT NULL AND s."arrived_at" IS NOT NULL AND s."arrived_at" < s."appointment_start")))) AS "dock_minutes", sum(CAST(greatest((s."raw_dwell_minutes" - s."free_minutes_granted"), 0::integer) AS bigint)) FILTER (WHERE (NOT (s."arrived_late" IS TRUE) AND s."schedule_type" = 'Open')) AS "open_minutes", sum(CAST(greatest((s."raw_dwell_minutes" - s."free_minutes_granted"), 0::integer) AS bigint)) FILTER (WHERE (NOT (s."arrived_late" IS TRUE) AND NOT (s."schedule_type" = 'Open') AND (s."appointment_start" IS NOT NULL AND s."arrived_at" IS NOT NULL AND s."arrived_at" < s."appointment_start"))) AS "early_minutes", sum(CAST(greatest((s."raw_dwell_minutes" - s."free_minutes_granted"), 0::integer) AS bigint)) FILTER (WHERE s."arrived_late" IS TRUE) AS "late_minutes", sum(s."raw_dwell_minutes") AS "dwell_minutes", sum(s."billable_amount") AS "billable_amount", sum(s."driver_pay_amount") AS "driver_pay_amount", sum(s."net_margin") AS "net_margin", sum(s."waived_amount") AS "waived_amount", count(*) FILTER (WHERE s."status" = 'Disputed') AS "disputed_stops", count(*) FILTER (WHERE s."suppressed_by_gate" IS TRUE) AS "suppressed_stops", count(*) FILTER (WHERE s."notice_deadline_at" IS NOT NULL) AS "notices_due", count(*) FILTER (WHERE (s."notice_deadline_at" IS NOT NULL AND s."notice_sent_at" IS NOT NULL AND s."notice_sent_at" <= s."notice_deadline_at")) AS "notices_on_time", count(*) FILTER (WHERE CASE WHEN (s."arrived_late" IS TRUE AND s."status" = 'NotBillable') THEN 'Late'::text WHEN s."suppressed_by_gate" IS TRUE THEN 'Notice'::text WHEN s."status" = 'Waived' THEN 'Waived'::text WHEN s."status" = 'Disputed' THEN 'Disputed'::text WHEN s."status" IN ('Accruing', 'Pending', 'Approved') THEN 'Pending'::text WHEN s."status" = 'Billed' THEN 'Billed'::text ELSE 'Other'::text END = 'Late') AS "recovery_late_stops", sum(s."gross_amount") FILTER (WHERE CASE WHEN (s."arrived_late" IS TRUE AND s."status" = 'NotBillable') THEN 'Late'::text WHEN s."suppressed_by_gate" IS TRUE THEN 'Notice'::text WHEN s."status" = 'Waived' THEN 'Waived'::text WHEN s."status" = 'Disputed' THEN 'Disputed'::text WHEN s."status" IN ('Accruing', 'Pending', 'Approved') THEN 'Pending'::text WHEN s."status" = 'Billed' THEN 'Billed'::text ELSE 'Other'::text END = 'Late') AS "recovery_late_gross", sum(s."billable_amount") FILTER (WHERE CASE WHEN (s."arrived_late" IS TRUE AND s."status" = 'NotBillable') THEN 'Late'::text WHEN s."suppressed_by_gate" IS TRUE THEN 'Notice'::text WHEN s."status" = 'Waived' THEN 'Waived'::text WHEN s."status" = 'Disputed' THEN 'Disputed'::text WHEN s."status" IN ('Accruing', 'Pending', 'Approved') THEN 'Pending'::text WHEN s."status" = 'Billed' THEN 'Billed'::text ELSE 'Other'::text END = 'Late') AS "recovery_late_billable", count(*) FILTER (WHERE CASE WHEN (s."arrived_late" IS TRUE AND s."status" = 'NotBillable') THEN 'Late'::text WHEN s."suppressed_by_gate" IS TRUE THEN 'Notice'::text WHEN s."status" = 'Waived' THEN 'Waived'::text WHEN s."status" = 'Disputed' THEN 'Disputed'::text WHEN s."status" IN ('Accruing', 'Pending', 'Approved') THEN 'Pending'::text WHEN s."status" = 'Billed' THEN 'Billed'::text ELSE 'Other'::text END = 'Notice') AS "recovery_notice_stops", sum(s."gross_amount