HEN 'Pending'::text WHEN s."status" = 'Billed' THEN 'Billed'::text ELSE 'Other'::text END = 'Pending') AS "recovery_pending_stops", sum(s."gross_amount") FILTER (WHERE CASE WHEN (s."arrived_late" IS TRUE AND s."status" = 'NotBillable') THEN 'Late'::text WHEN s."suppressed_by_gate" IS TRUE THEN 'Notice'::text WHEN s."status" = 'Waived' THEN 'Waived'::text WHEN s."status" = 'Disputed' THEN 'Disputed'::text WHEN s."status" IN ('Accruing', 'Pending', 'Approved') THEN 'Pending'::text WHEN s."status" = 'Billed' THEN 'Billed'::text ELSE 'Other'::text END = 'Pending') AS "recovery_pending_gross", sum(s."billable_amount") FILTER (WHERE CASE WHEN (s."arrived_late" IS TRUE AND s."status" = 'NotBillable') THEN 'Late'::text WHEN s."suppressed_by_gate" IS TRUE THEN 'Notice'::text WHEN s."status" = 'Waived' THEN 'Waived'::text WHEN s."status" = 'Disputed' THEN 'Disputed'::text WHEN s."status" IN ('Accruing', 'Pending', 'Approved') THEN 'Pending'::text WHEN s."status" = 'Billed' THEN 'Billed'::text ELSE 'Other'::text END = 'Pending') AS "recovery_pending_billable", count(*) FILTER (WHERE CASE WHEN (s."arrived_late" IS TRUE AND s."status" = 'NotBillable') THEN 'Late'::text WHEN s."suppressed_by_gate" IS TRUE THEN 'Notice'::text WHEN s."status" = 'Waived' THEN 'Waived'::text WHEN s."status" = 'Disputed' THEN 'Disputed'::text WHEN s."status" IN ('Accruing', 'Pending', 'Approved') THEN 'Pending'::text WHEN s."status" = 'Billed' THEN 'Billed'::text ELSE 'Other'::text END = 'Billed') AS "recovery_billed_stops", sum(s."gross_amount") FILTER (WHERE CASE WHEN (s."arrived_late" IS TRUE AND s."status" = 'NotBillable') THEN 'Late'::text WHEN s."suppressed_by_gate" IS TRUE THEN 'Notice'::text WHEN s."status" = 'Waived' THEN 'Waived'::text WHEN s."status" = 'Disputed' THEN 'Disputed'::text WHEN s."status" IN ('Accruing', 'Pending', 'Approved') THEN 'Pending'::text WHEN s."status" = 'Billed' THEN 'Billed'::text ELSE 'Other'::text END = 'Billed') AS "recovery_billed_gross", sum(s."billable_amount") FILTER (WHERE CASE WHEN (s."arrived_late" IS TRUE AND s."status" = 'NotBillable') THEN 'Late'::text WHEN s."suppressed_by_gate" IS TRUE THEN 'Notice'::text WHEN s."status" = 'Waived' THEN 'Waived'::text WHEN s."status" = 'Disputed' THEN 'Disputed'::text WHEN s."status" IN ('Accruing', 'Pending', 'Approved') THEN 'Pending'::text WHEN s."status" = 'Billed' THEN 'Billed'::text ELSE 'Other'::text END = 'Billed') AS "recovery_billed_billable", count(*) FILTER (WHERE CASE WHEN (s."arrived_late" IS TRUE AND s."status" = 'NotBillable') THEN 'Late'::text WHEN s."suppressed_by_gate" IS TRUE THEN 'Notice'::text WHEN s."status" = 'Waived' THEN 'Waived'::text WHEN s."status" = 'Disputed' THEN 'Disputed'::text WHEN s."status" IN ('Accruing', 'Pending', 'Approved') THEN 'Pending'::text WHEN s."status" = 'Billed' THEN 'Billed'::text ELSE 'Other'::text END = 'Other') AS "recovery_other_stops", sum(s."gross_amount") FILTER (WHERE CASE WHEN (s."arrived_late" IS TRUE AND s."status" = 'NotBillable') THEN 'Late'::text WHEN s."suppressed_by_gate" IS TRUE THEN 'Notice'::text WHEN s."status" = 'Waived' THEN 'Waived'::text WHEN s."status" = 'Disputed' THEN 'Disputed'::text WHEN s."status" IN ('Accruing', 'Pending', 'Approved') THEN 'Pending'::text WHEN s."status" = 'Billed' THEN 'Billed'::text ELSE 'Other'::text END = 'Other') AS "recovery_other_gross", sum(s."billable_amount") FILTER (WHERE CASE WHEN (s."arrived_late" IS TRUE AND s."status" = 'NotBillable') THEN 'Late'::text WHEN s."suppressed_by_gate" IS TRUE THEN 'Notice'::text WHEN s."status" = 'Waived' THEN 'Waived'::text WHEN s."status" = 'Disputed' THEN 'Disputed'::text WHEN s."status" IN ('Accruing', 'Pending', 'Approved') THEN 'Pending'::text WHEN s."status" = 'Billed' THEN 'Billed'::text ELSE 'Other'::text END = 'Other') AS "recovery_other_billable", count(*) FILTER (WHERE s."stop_type" IN ('Pickup', 'SplitPickup')) AS "split_pickup_stops", count(*) FILTER (WHERE (s."stop_type" IN ('Pickup', 'SplitPickup') AND CAST(greatest((s."r